$("scene-flow").addEventListener("click",event=>{if(Scene.pendingPrompt?.kind!=="fodder-round-batch")return;const preset=event.target.closest("[data-fodder-batch-preset]"),submit=event.target.closest("[data-fodder-batch-submit]");if(!preset&&!submit)return;if(!canControlScenePrompt())return toast("Распределение массовки подтверждает Нарратор");const selects=[...$("scene-flow").querySelectorAll("[data-fodder-batch-zone]")];if(preset){const mode=preset.dataset.fodderBatchPreset;if(mode==="clear")selects.forEach(select=>select.value="");if(mode==="focus"){const target=$("scene-flow").querySelector("[data-fodder-batch-focus]")?.value;selects.forEach(select=>select.value=target&&[...select.options].some(option=>option.value===target)?target:"")}if(mode==="spread"){const counts=new Map();selects.forEach(select=>{const candidates=[...select.options].map(option=>option.value).filter(Boolean).sort((a,b)=>Number(counts.get(a)||0)-Number(counts.get(b)||0)||a.localeCompare(b)),target=candidates[0]||"";select.value=target;if(target)counts.set(target,Number(counts.get(target)||0)+1)})}updateFodderBatchSummary();return}const assignments=Object.fromEntries(selects.map(select=>[select.dataset.fodderBatchZone,select.value])),prepared=SceneEngine.respondRulePrompt(Scene,D,{choice:"custom",assignments});if(!prepared.ok)return toast(prepared.errors.join(" "));if(commitSceneEvents("Массовка: пакетный урон",prepared.events))toast("Урон массовки применён одним пакетом")});
