// Narrator cleanup must remain available even when a rules chain is stale.
document.addEventListener("click",event=>{
  if(activeSceneView()!=="gm"||!(Scene.pendingAction||Scene.pendingPrompt||Scene.pendingActionPlan))return;
  const removeActor=event.target.closest("[data-scene-remove-actor]"),removeNpcs=event.target.closest("#scene-remove-npcs");
  if(!removeActor&&!removeNpcs)return;
  event.preventDefault();event.stopImmediatePropagation();
  if(removeActor){
    const actor=Scene.actors.find(item=>item.id===removeActor.dataset.sceneRemoveActor);
    if(actor&&window.confirm(`Убрать «${actor.name}»? Незавершённые цепочки с его участием будут безопасно закрыты.`))commitScene(`Убран участник «${actor.name}»`,scene=>{scene.actors=scene.actors.filter(item=>item.id!==actor.id);scene.objects=scene.objects.filter(item=>item.ownerActorId!==actor.id);scene.markers=scene.markers.filter(item=>item.ownerActorId!==actor.id);scene.targetIds=scene.targetIds.filter(id=>id!==actor.id);if(scene.selectedActor===actor.id)scene.selectedActor=null;if(scene.activeActorId===actor.id)scene.activeActorId=null});
    return;
  }
  const removed=Scene.actors.filter(actor=>actor.kind==="enemy"||actor.profileId||actor.kind==="crowd"||actor.kind==="token");
  if(!removed.length)return toast("На столе нет НПС или свободных токенов");
  if(!window.confirm(`Убрать НПС и свободные токены (${removed.length})? Незавершённые цепочки будут безопасно закрыты.`))return;
  const ids=new Set(removed.map(actor=>actor.id));
  commitScene("Убраны НПС и свободные токены",scene=>{scene.actors=scene.actors.filter(actor=>!ids.has(actor.id));scene.objects=scene.objects.filter(object=>!ids.has(object.ownerActorId));scene.markers=scene.markers.filter(marker=>!ids.has(marker.ownerActorId));scene.targetIds=scene.targetIds.filter(id=>!ids.has(id));if(ids.has(scene.selectedActor))scene.selectedActor=null;if(ids.has(scene.activeActorId))scene.activeActorId=null});
},true);

